import{_ as t,o as e,c as s,ai as n}from"./chunks/framework.BBSijY9B.js";const u=JSON.parse('{"title":"每日简报类自动化实例","description":"手把手搭建一个每天早上自动送达的个人简报，涵盖邮件、日程、行业动态。","frontmatter":{"related":["/templates/daily-briefer","/automation/routines","/roles/managers"],"title":"每日简报类自动化实例","description":"手把手搭建一个每天早上自动送达的个人简报，涵盖邮件、日程、行业动态。","section":"automation","order":4,"tags":["自动化","例程","简报","实例"],"sources":["https://docs.x.ai/grok-bot/skills-routines-and-automations","https://cursor.com/docs/grok-bot/work"],"wordCount":402,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"每日简报类自动化实例 | WANGXXXL"}],["meta",{"property":"og:description","content":"手把手搭建一个每天早上自动送达的个人简报，涵盖邮件、日程、行业动态。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/automation/daily-briefing"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/automation-daily-briefing-9550cd7f2f.png"}],["meta",{"property":"og:image:alt","content":"每日简报类自动化实例 · WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"每日简报类自动化实例 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"手把手搭建一个每天早上自动送达的个人简报，涵盖邮件、日程、行业动态。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/automation-daily-briefing-9550cd7f2f.png"}],["meta",{"name":"twitter:image:alt","content":"每日简报类自动化实例 · WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/automation/daily-briefing"}]]},"headers":[],"relativePath":"automation/daily-briefing.md","filePath":"automation/daily-briefing.md","lastUpdated":1792487553000}'),i={name:"automation/daily-briefing.md"};function o(l,a,p,r,c,d){return e(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="每日简报类自动化实例" tabindex="-1">每日简报类自动化实例 <a class="header-anchor" href="#每日简报类自动化实例" aria-label="Permalink to &quot;每日简报类自动化实例&quot;">​</a></h1><p>&quot;每天早上醒来，手机上已经有一份为我准备好的简报&quot;——这是最适合新手的第一个完整自动化。下面一步步搭起来。</p><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>每个工作日早上 7:30，Bot 在对话里发一份简报，包括：</p><ol><li>今天的日程和需要准备的事；</li><li>过去 24 小时需要我处理的邮件；</li><li>我关注领域的 5 条重要动态。</li></ol><h2 id="第一步-建一个专职-bot" tabindex="-1">第一步：建一个专职 Bot <a class="header-anchor" href="#第一步-建一个专职-bot" aria-label="Permalink to &quot;第一步：建一个专职 Bot&quot;">​</a></h2><p>新建 Bot，取名&quot;早报&quot;，发入职说明：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的岗位是&quot;早报&quot;，每天帮我准备一份晨间简报。</span></span>
<span class="line"><span>可用工具：Gmail、日历、网页浏览。</span></span>
<span class="line"><span>边界：只读，不发送、不回复、不删除任何内容。</span></span>
<span class="line"><span>风格：简洁，先结论后细节，总长度控制在手机一屏半以内。请记住。</span></span></code></pre></div><h2 id="第二步-手动跑一次" tabindex="-1">第二步：手动跑一次 <a class="header-anchor" href="#第二步-手动跑一次" aria-label="Permalink to &quot;第二步：手动跑一次&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>现在手动做一次今天的简报：</span></span>
<span class="line"><span>【日程】今天的会议，每个会写时间、参与人、需要我提前看的材料；</span></span>
<span class="line"><span>【邮件】过去 24 小时里需要我回复或决定的邮件，最多 8 封，每封一句话摘要 + 链接；</span></span>
<span class="line"><span>【动态】在以下来源中挑 5 条最重要的更新：（列出你关注的网站或 X 账号）。</span></span>
<span class="line"><span>某个来源打不开就注明，不要编。</span></span></code></pre></div><p>看结果，提意见，改到满意为止。常见调整：邮件筛选太松、动态太泛、格式太长。</p><h2 id="第三步-存成技能" tabindex="-1">第三步：存成技能 <a class="header-anchor" href="#第三步-存成技能" aria-label="Permalink to &quot;第三步：存成技能&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把刚才最终版本的做法保存为技能&quot;晨间简报&quot;，包含来源清单、筛选标准和输出格式。</span></span></code></pre></div><h2 id="第四步-设例程并测试" tabindex="-1">第四步：设例程并测试 <a class="header-anchor" href="#第四步-设例程并测试" aria-label="Permalink to &quot;第四步：设例程并测试&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每个工作日早上 7:30（按你所在的时区）运行&quot;晨间简报&quot;技能，结果发在这个对话里。</span></span>
<span class="line"><span>如果邮箱或日历连接失效，在简报开头提醒我重新授权。现在先测试运行一次。</span></span></code></pre></div><h2 id="第五步-观察一周再微调" tabindex="-1">第五步：观察一周再微调 <a class="header-anchor" href="#第五步-观察一周再微调" aria-label="Permalink to &quot;第五步：观察一周再微调&quot;">​</a></h2><p>第一周每天花两分钟看简报，记下&quot;多余的&quot;和&quot;漏掉的&quot;，周末一次性告诉它：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这一周的反馈：抄送我的群发邮件不用列；动态里少放融资新闻，多放产品更新。请更新技能。</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">再加一点料</p><p>熟练以后可以扩展：加上天气和通勤提醒、待办清单里今天到期的任务，或者让它用语音备忘读给你听。</p></div><div class="warning custom-block"><p class="custom-block-title">用量意识</p><p>例程每次运行都会消耗用量。简报类任务每天一次通常足够，不要设成每小时一次。具体额度以官方最新说明为准。</p></div><h2 id="变体思路" tabindex="-1">变体思路 <a class="header-anchor" href="#变体思路" aria-label="Permalink to &quot;变体思路&quot;">​</a></h2><ul><li><strong>周报版</strong>：每周五下午汇总本周完成事项和下周计划。</li><li><strong>团队版</strong>：汇总项目仓库的新 Issue 和代码合并情况。</li><li><strong>社交版</strong>：汇总自己账号的新提及和值得回复的评论（只出草稿）。</li></ul>`,22)])])}const g=t(i,[["render",o]]);export{u as __pageData,g as default};
